Object.assign(SNIP,{});PRESET_NOTES["l31"]={"Ví dụ: Đếm số lần xuất hiện của từ": "Mỗi từ được băm vào một bucket; dem[w[i]]++ tự tạo khóa mới với giá trị 0 rồi tăng lên 1. count(\"ca\") hỏi mà không tạo khóa. Có 4 từ khác nhau.", "Ví dụ: Hai số có tổng bằng X": "Với mỗi j, hỏi “đã gặp X − a[j] chưa, ở đâu?”. Tới j = 3 (a[3] = 5) thì cần 7, chưa gặp; tới j = 4 (a[4] = 7) cần 5, đã gặp ở chỉ số 3. Một lần duyệt O(n), không cần sắp xếp.", "Ví dụ: Nhóm các từ là hoán vị của nhau": "Hai từ là hoán vị của nhau khi và chỉ khi sắp xếp các chữ cái thì giống nhau. Dùng chuỗi đã sắp xếp làm khóa: 3 nhóm, nhóm “aet” có 3 từ.", "Cạm bẫy: đọc khóa chưa có": "Chỉ một lần đọc tuoi[\"chi\"] mà bảng đã có 3 phần tử. count không tạo thêm khóa nên size vẫn là 3. Với Python và C#, cùng đoạn code này dừng hẳn với lỗi: thử chuyển ngôn ngữ để xem."};EX_HINTS["l31"]=[["Đi j từ trái sang phải. Hỏi bảng: đã gặp giá trị X − aⱼ chưa? Có thì in ngay: j đó là j nhỏ nhất.", "Chỉ ghi vị trí của một giá trị lần đầu gặp nó, để i là nhỏ nhất.", "Tổng có thể tới 2·10^9: dùng long long."], ["Đoạn (l, r] có tổng K ⇔ pre[r] − pre[l] = K ⇔ pre[l] = pre[r] − K.", "Giữ từ điển “tổng tiền tố → số lần đã gặp”, bắt đầu với dem[0] = 1 (tiền tố rỗng). Với mỗi r: cộng dem[pre − K] vào kết quả, rồi tăng dem[pre].", "Có số âm nên không dùng được hai con trỏ như Bài 12. Kết quả có thể tới khoảng n²/2: dùng long long."], ["Hai từ là hoán vị của nhau ⇔ sắp xếp các chữ cái thì giống nhau. Dùng chuỗi đã sắp xếp làm khóa.", "sort(w.begin(), w.end()) sắp xếp các chữ cái của chuỗi w.", "Duyệt từ điển để tìm giá trị lớn nhất: for (auto& p : nhom), p.second là số từ."]];
