const PR31=[{label:"Ví dụ: Đếm số lần xuất hiện của từ",input:"",code:"#include <iostream>\n#include <string>\n#include <unordered_map>\n#include <unordered_set>\nusing namespace std;\n\nint main() {\n    string w[8] = {\"meo\", \"cho\", \"ga\", \"meo\", \"vit\", \"cho\", \"meo\", \"ga\"};\n    unordered_map<string, int> dem;\n    for (int i = 0; i < 8; i++) dem[w[i]]++;     // khóa mới tự bắt đầu từ 0\n    cout << dem[\"meo\"] << \" \" << dem[\"cho\"] << \" \" << dem.count(\"ca\") << \"\\n\";\n    cout << dem.size() << \"\\n\";\n    return 0;\n}",viz:[{type:"cont",of:"dem"}],py:{code:"w = [\"meo\", \"cho\", \"ga\", \"meo\", \"vit\", \"cho\", \"meo\", \"ga\"]\ndem = {}\nfor x in w:\n    dem[x] = dem.get(x, 0) + 1     # khóa chưa có: get trả về 0\nprint(dem[\"meo\"], dem[\"cho\"], \"ca\" in dem)\nprint(len(dem))",viz:[{type:"cont",of:"dem",as:"dict"}],note:"dem.get(x, 0) đọc giá trị, khóa chưa có thì lấy 0 mà không báo lỗi. dict giữ thứ tự thêm vào. Viết gọn hơn: from collections import Counter; dem = Counter(w)."},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        string[] w = { \"meo\", \"cho\", \"ga\", \"meo\", \"vit\", \"cho\", \"meo\", \"ga\" };\n        Dictionary<string, int> dem = new Dictionary<string, int>();\n        foreach (string x in w)\n        {\n            dem[x] = dem.GetValueOrDefault(x) + 1;     // khóa chưa có: lấy 0\n        }\n        Console.WriteLine(dem[\"meo\"] + \" \" + dem[\"cho\"] + \" \" + dem.ContainsKey(\"ca\"));\n        Console.WriteLine(dem.Count);\n    }\n}",viz:[{type:"cont",of:"dem",as:"dict"}],note:"GetValueOrDefault(x) đọc giá trị, khóa chưa có thì trả về 0 mà không ném lỗi. ContainsKey hỏi mà không tạo khóa. Có 4 từ khác nhau."}},{label:"Ví dụ: Hai số có tổng bằng X",input:"",code:"#include <iostream>\n#include <string>\n#include <unordered_map>\n#include <unordered_set>\nusing namespace std;\n\nint main() {\n    int a[7] = {8, 3, 11, 5, 7, 2, 9};\n    int X = 12;\n    unordered_map<int, int> viTri;     // giá trị → chỉ số đã gặp\n    for (int j = 0; j < 7; j++) {\n        int can = X - a[j];\n        if (viTri.count(can)) {\n            cout << viTri[can] << \" \" << j << \"\\n\";\n            return 0;\n        }\n        viTri[a[j]] = j;\n    }\n    cout << -1 << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["j"]},{type:"cont",of:"viTri"}],py:{code:"a = [8, 3, 11, 5, 7, 2, 9]\nX = 12\nviTri = {}          # giá trị → chỉ số đã gặp\nkq = -1\nfor j in range(len(a)):\n    can = X - a[j]\n    if can in viTri:\n        kq = (viTri[can], j)\n        break\n    viTri[a[j]] = j\nprint(kq)",viz:[{type:"cells",of:"a",ptr:["j"]},{type:"cont",of:"viTri",as:"dict"}]},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] a = { 8, 3, 11, 5, 7, 2, 9 };\n        int X = 12;\n        Dictionary<int, int> viTri = new Dictionary<int, int>();     // giá trị → chỉ số đã gặp\n        for (int j = 0; j < a.Length; j++)\n        {\n            int can = X - a[j];\n            if (viTri.TryGetValue(can, out int i))\n            {\n                Console.WriteLine(i + \" \" + j);\n                return;\n            }\n            viTri[a[j]] = j;\n        }\n        Console.WriteLine(-1);\n    }\n}",viz:[{type:"cells",of:"a",ptr:["j"]},{type:"cont",of:"viTri",as:"dict"}],note:"TryGetValue vừa hỏi vừa lấy giá trị trong một lần tra. Tới j = 4 (a[4] = 7) cần 5, đã gặp ở chỉ số 3."}},{label:"Ví dụ: Nhóm các từ là hoán vị của nhau",input:"",code:"#include <iostream>\n#include <string>\n#include <algorithm>\n#include <unordered_map>\nusing namespace std;\n\nint main() {\n    string w[6] = {\"eat\", \"tea\", \"tan\", \"ate\", \"nat\", \"bat\"};\n    unordered_map<string, int> nhom;     // chuỗi đã sắp xếp → số từ trong nhóm\n    for (int i = 0; i < 6; i++) {\n        string k = w[i];\n        sort(k.begin(), k.end());       // \"tea\" → \"aet\"\n        nhom[k]++;\n    }\n    cout << nhom.size() << \" \" << nhom[\"aet\"] << \"\\n\";\n    return 0;\n}",viz:[{type:"cont",of:"nhom"},{type:"vars",names:["k"]}],py:{code:"w = [\"eat\", \"tea\", \"tan\", \"ate\", \"nat\", \"bat\"]\nnhom = {}           # chuỗi đã sắp xếp → các từ trong nhóm\nfor x in w:\n    k = \"\".join(sorted(x))         # \"tea\" → \"aet\"\n    if k not in nhom:\n        nhom[k] = []\n    nhom[k].append(x)\nprint(len(nhom), nhom[\"aet\"])",viz:[{type:"cont",of:"nhom",as:"dict"},{type:"vars",names:["k"]}],note:"Khóa là chuỗi đã sắp xếp các chữ cái; giá trị là list các từ của nhóm. 3 nhóm, nhóm “aet” gồm eat, tea, ate."},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        string[] w = { \"eat\", \"tea\", \"tan\", \"ate\", \"nat\", \"bat\" };\n        Dictionary<string, int> nhom = new Dictionary<string, int>();   // chuỗi đã sắp xếp → số từ\n        foreach (string x in w)\n        {\n            char[] c = x.ToCharArray();\n            Array.Sort(c);\n            string k = new string(c);          // \"tea\" → \"aet\"\n            nhom[k] = nhom.GetValueOrDefault(k) + 1;\n        }\n        Console.WriteLine(nhom.Count + \" \" + nhom[\"aet\"]);\n    }\n}",viz:[{type:"cont",of:"nhom",as:"dict"}]}},{label:"Cạm bẫy: đọc khóa chưa có",input:"",code:"#include <iostream>\n#include <string>\n#include <unordered_map>\n#include <unordered_set>\nusing namespace std;\n\nint main() {\n    unordered_map<string, int> tuoi;\n    tuoi[\"an\"] = 15;\n    tuoi[\"binh\"] = 16;\n    if (tuoi[\"chi\"] > 0) cout << \"co chi\\n\";    // đọc khóa chưa có: tự tạo \"chi\" → 0\n    cout << tuoi.size() << \"\\n\";\n    cout << tuoi.count(\"dung\") << \" \" << tuoi.size() << \"\\n\";\n    return 0;\n}",viz:[{type:"cont",of:"tuoi"}],py:{code:"tuoi = {}\ntuoi[\"an\"] = 15\ntuoi[\"binh\"] = 16\nif tuoi[\"chi\"] > 0:            # khóa chưa có: KeyError\n    print(\"co chi\")\nprint(len(tuoi))",viz:[{type:"cont",of:"tuoi",as:"dict"}],note:"Python không tự tạo khóa như C++: đọc tuoi[\"chi\"] khi chưa có làm chương trình dừng với KeyError: 'chi'. Sửa: if tuoi.get(\"chi\", 0) > 0 hoặc if \"chi\" in tuoi and tuoi[\"chi\"] > 0."},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        Dictionary<string, int> tuoi = new Dictionary<string, int>();\n        tuoi[\"an\"] = 15;\n        tuoi[\"binh\"] = 16;\n        if (tuoi[\"chi\"] > 0) Console.WriteLine(\"co chi\");    // khóa chưa có: ném lỗi\n        Console.WriteLine(tuoi.Count);\n    }\n}",viz:[{type:"cont",of:"tuoi",as:"dict"}],note:"C# không tự tạo khóa như C++: đọc tuoi[\"chi\"] khi chưa có ném KeyNotFoundException. Sửa: tuoi.GetValueOrDefault(\"chi\") > 0, hoặc dùng TryGetValue."}}];
