makeEx2(document.getElementById("ex-l31"),sim31,[{t:"Hai số có tổng bằng X",d:"Đầu vào: dòng 1 là n và X (2 ≤ n ≤ 10^5, |X| ≤ 2·10^9); dòng 2 là n số nguyên (|aᵢ| ≤ 10^9). Đầu ra: hai chỉ số i < j (đánh số từ 1) với aᵢ + aⱼ = X; chọn j nhỏ nhất có thể, và với j đó chọn i nhỏ nhất. Không có thì in -1.",tests:[{in:"7 12\n8 3 11 5 7 2 9",out:"4 5"},{in:"2 3\n1 2",out:"1 2"},{in:"2 4\n1 2",out:"-1"},{in:"3 10\n5 5 5",out:"1 2"},{in:"5 0\n-3 7 10 -10 0",out:"3 4"},{in:"2 2000000000\n1000000000 1000000000",out:"1 2"},{in:"4 5\n4 1 4 1",out:"1 2"}],start:"#include <iostream>\n#include <string>\n#include <unordered_map>\n#include <unordered_set>\nusing namespace std;\n\nint main() {\n    int n;\n    long long X;\n    cin >> n >> X;\n    unordered_map<long long, int> viTri;     // giá trị → chỉ số đầu tiên đã gặp\n    for (int j = 1; j <= n; j++) {\n        long long x;\n        cin >> x;\n        // đã gặp X - x chưa?\n    }\n    cout << -1 << \"\\n\";\n    return 0;\n}",perf:{gen:n=>n+" 1\n"+Array.from({length:n},(_,i)=>i*2).join(" "),ns:[500,2000,8000],need:"n",limit:n=>60*n+200,why:"Thử mọi cặp là O(n²). Bảng băm trả lời “đã gặp X − aⱼ chưa?” trong O(1)."},py:{start:"n, X = map(int, input().split())\na = list(map(int, input().split()))\nviTri = {}          # giá trị → chỉ số đầu tiên đã gặp (đánh số từ 1)\nfor j in range(1, n + 1):\n    x = a[j - 1]\n    # đã gặp X - x chưa?\nprint(-1)",hints:["Đi j từ trái sang phải. Hỏi từ điển: đã gặp giá trị X − aⱼ chưa? Có thì đó là đáp án (j nhỏ nhất).","Chỉ ghi vị trí của một giá trị lần đầu gặp nó, để i là nhỏ nhất.","Đừng dùng X - x in a[:j]: tìm trong list là O(n)."]},cs:{start:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        string[] t = Console.ReadLine().Split();\n        int n = int.Parse(t[0]);\n        long X = long.Parse(t[1]);\n        long[] a = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n        Dictionary<long, int> viTri = new Dictionary<long, int>();   // giá trị → chỉ số đầu tiên (đánh số từ 1)\n        for (int j = 1; j <= n; j++)\n        {\n            long x = a[j - 1];\n            // đã gặp X - x chưa?\n        }\n        Console.WriteLine(-1);\n    }\n}",hints:["Đi j từ trái sang phải. Hỏi từ điển: đã gặp giá trị X − aⱼ chưa? Có thì đó là đáp án (j nhỏ nhất).","Chỉ ghi vị trí của một giá trị lần đầu gặp nó (kiểm tra ContainsKey), để i là nhỏ nhất.","Tổng có thể tới 2·10^9: dùng long."]}},{t:"Đếm đoạn con có tổng bằng K",d:"Đầu vào: dòng 1 là n và K (1 ≤ n ≤ 10^5, |K| ≤ 10^14); dòng 2 là n số nguyên (|aᵢ| ≤ 10^9, có thể âm). Đầu ra: số đoạn con liên tiếp có tổng đúng bằng K.",tests:[{in:"3 2\n1 1 1",out:"2"},{in:"3 3\n1 2 3",out:"2"},{in:"3 0\n1 -1 0",out:"3"},{in:"1 5\n5",out:"1"},{in:"8 7\n3 4 7 2 -3 1 4 2",out:"4"},{in:"4 0\n0 0 0 0",out:"10"},{in:"3 0\n-1 -1 1",out:"1"}],start:"#include <iostream>\n#include <string>\n#include <unordered_map>\n#include <unordered_set>\nusing namespace std;\n\nint main() {\n    int n;\n    long long K;\n    cin >> n >> K;\n    unordered_map<long long, long long> dem;   // tổng tiền tố → số lần đã gặp\n    dem[0] = 1;\n    long long pre = 0, kq = 0;\n    for (int i = 0; i < n; i++) {\n        long long x;\n        cin >> x;\n        pre += x;\n        // đoạn kết thúc tại i có tổng K ↔ trước đó có tổng tiền tố pre - K\n    }\n    cout << kq << \"\\n\";\n    return 0;\n}",perf:{gen:n=>n+" 0\n"+Array.from({length:n},(_,i)=>i%2?1:-1).join(" "),ns:[500,2000,8000],need:"n",limit:n=>60*n+200,why:"Thử mọi đoạn là O(n²). Tổng tiền tố cộng từ điển đếm cho O(n)."},py:{start:"n, K = map(int, input().split())\na = list(map(int, input().split()))\ndem = {0: 1}        # tổng tiền tố → số lần đã gặp\npre = kq = 0\nfor x in a:\n    pre += x\n    # đoạn kết thúc ở đây có tổng K ↔ trước đó có tổng tiền tố pre - K\nprint(kq)",hints:["Đoạn (l, r] có tổng K ⇔ pre[r] − pre[l] = K ⇔ pre[l] = pre[r] − K.","Giữ dict “tổng tiền tố → số lần đã gặp”, bắt đầu với {0: 1}. Với mỗi phần tử: cộng dem.get(pre − K, 0) vào kết quả, rồi tăng dem[pre].","Có số âm nên không dùng được hai con trỏ như Bài 12."]},cs:{start:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        string[] t = Console.ReadLine().Split();\n        int n = int.Parse(t[0]);\n        long K = long.Parse(t[1]);\n        long[] a = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n        Dictionary<long, long> dem = new Dictionary<long, long>();   // tổng tiền tố → số lần đã gặp\n        dem[0] = 1;\n        long pre = 0, kq = 0;\n        foreach (long x in a)\n        {\n            pre += x;\n            // đoạn kết thúc ở đây có tổng K ↔ trước đó có tổng tiền tố pre - K\n        }\n        Console.WriteLine(kq);\n    }\n}",hints:["Đoạn (l, r] có tổng K ⇔ pre[r] − pre[l] = K ⇔ pre[l] = pre[r] − K.","Giữ Dictionary “tổng tiền tố → số lần đã gặp”, bắt đầu với dem[0] = 1. Với mỗi phần tử: cộng số lần đã gặp pre − K, rồi tăng dem[pre].","Có số âm nên không dùng được hai con trỏ như Bài 12."]}},{t:"Nhóm các từ là hoán vị",d:"Đầu vào: n (1 ≤ n ≤ 10^4) và n từ gồm chữ thường (mỗi từ dài 1 … 10), cách nhau dấu cách. Hai từ cùng nhóm nếu từ này là hoán vị các chữ cái của từ kia. Đầu ra: số nhóm và số từ của nhóm đông nhất.",tests:[{in:"6\neat tea tan ate nat bat",out:"3 3"},{in:"1\na",out:"1 1"},{in:"3\nab ba ab",out:"1 3"},{in:"3\nabc def ghi",out:"3 1"},{in:"6\nlisten silent enlist google gogole inlets",out:"2 4"}],start:"#include <iostream>\n#include <string>\n#include <algorithm>\n#include <unordered_map>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    unordered_map<string, int> nhom;\n    for (int i = 0; i < n; i++) {\n        string w;\n        cin >> w;\n        // khóa: w sau khi sắp xếp các chữ cái\n    }\n    int lonNhat = 0;\n    cout << nhom.size() << \" \" << lonNhat << \"\\n\";\n    return 0;\n}",py:{start:"n = int(input())\nw = input().split()\nnhom = {}\n# khóa: từ sau khi sắp xếp các chữ cái\nlonNhat = 0\nprint(len(nhom), lonNhat)",hints:["Hai từ là hoán vị của nhau ⇔ sắp xếp các chữ cái thì giống nhau. \"\".join(sorted(x)) cho chuỗi đã sắp xếp.","Đếm số từ của mỗi khóa bằng dict (hoặc Counter).","max(nhom.values()) là nhóm đông nhất."]},cs:{start:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        string[] w = Console.ReadLine().Split();\n        Dictionary<string, int> nhom = new Dictionary<string, int>();\n        // khóa: từ sau khi sắp xếp các chữ cái\n        int lonNhat = 0;\n        Console.WriteLine(nhom.Count + \" \" + lonNhat);\n    }\n}",hints:["Hai từ là hoán vị của nhau ⇔ sắp xếp các chữ cái thì giống nhau.","Sắp xếp chữ cái: char[] c = x.ToCharArray(); Array.Sort(c); new string(c).","Duyệt foreach (var kv in nhom), kv.Value là số từ của nhóm."]}}]);

makeQuiz("quiz31","score31",[{"q": "Thời gian trung bình để kiểm tra một khóa có trong bảng băm?", "o": ["O(1)", "O(log n)", "O(n)", "O(n log n)"], "a": 0, "e": "Trung bình O(1); trường hợp xấu nhất (mọi khóa va chạm) là O(n)."}, {"q": "Tìm hai số có tổng X bằng bảng băm: với mỗi a[j], cần hỏi gì?", "o": ["a[j] đã có trong bảng chưa", "X − a[j] đã gặp chưa", "X + a[j] có trong bảng không", "a[j] có lớn hơn X không"], "a": 1, "e": "Cặp (i, j) có a[i] = X − a[j]."}, {"q": "Nhóm các từ là hoán vị của nhau, khóa tốt nhất là gì?", "o": ["Độ dài từ", "Chữ cái đầu tiên", "Từ sau khi sắp xếp các chữ cái", "Tổng mã các chữ cái"], "a": 2, "e": "Tổng mã có thể trùng giữa hai từ không phải hoán vị (“ad” và “bc”)."}, {"q": "Đếm đoạn con có tổng K bằng tổng tiền tố: vì sao phải khởi tạo dem[0] = 1?", "o": ["Để tránh lỗi chia cho 0", "Để tính cả các đoạn bắt đầu từ phần tử đầu tiên (tiền tố rỗng có tổng 0)", "Vì từ điển không được rỗng", "Không cần thiết"], "a": 1, "e": "Đoạn a[0..r] có tổng pre[r] − 0."}]);

